<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  :root { --bg:#0a0e14; --panel:#0d1117; --line:#21262d; --txt:#c9d1d9; --accent:#3fb950; }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    background: radial-gradient(1200px 800px at 50% -10%, #121926 0%, var(--bg) 60%);
    color: var(--txt);
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100%;
  }
  .app { text-align: center; padding: 16px; }
  h1 {
    margin: 0 0 4px;
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 0.5px;
  }
  .hud {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
    margin: 6px 0 14px;
    min-height: 28px;
  }
  #score {
    font-size: 18px;
    font-weight: 600;
    padding: 6px 14px;
    border-radius: 999px;
    background: var(--panel);
    border: 1px solid var(--line);
    min-width: 120px;
  }
  .controls { display: flex; gap: 10px; justify-content: center; margin-bottom: 14px; }
  button {
    font: inherit;
    font-weight: 600;
    color: var(--txt);
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 9px 18px;
    cursor: pointer;
    transition: transform .05s ease, background .15s ease, border-color .15s ease;
  }
  button:hover { background: #161b22; border-color: #30363d; }
  button:active { transform: translateY(1px); }
  #start { background: var(--accent); color: #06210d; border-color: var(--accent); }
  #start:hover { background: #4cc765; }
  .board-wrap { line-height: 0; display: inline-block; }
  #snake {
    background: var(--panel);
    border-radius: 14px;
    box-shadow: 0 12px 40px rgba(0,0,0,.55), inset 0 0 0 1px var(--line);
    min-width: 400px;
    min-height: 400px;
    width: 480px;
    height: 480px;
    touch-action: none;
  }
  .hint { margin-top: 12px; font-size: 12.5px; color: #8b949e; }
  kbd {
    background: var(--panel);
    border: 1px solid var(--line);
    border-bottom-width: 2px;
    border-radius: 6px;
    padding: 1px 6px;
    font-size: 11px;
  }
</style>
</head>
<body>
  <div class="app">
    <h1>🐍 Snake</h1>
    <div class="hud"><div id="score">Score: 0</div></div>
    <div class="controls">
      <button id="start">Start</button>
      <button id="pause">Pause</button>
      <button id="reset">Reset</button>
    </div>
    <div class="board-wrap">
      <canvas id="snake" width="480" height="480"></canvas>
    </div>
    <div class="hint">Use <kbd>↑</kbd><kbd>↓</kbd><kbd>←</kbd><kbd>→</kbd> to steer · <kbd>Space</kbd> to pause</div>
  </div>

<script>
(function () {
  "use strict";

  // ---- Grid / board config -------------------------------------------------
  var W = 20, H = 20;          // cells (>= 10)
  var CELL = 24;               // px per cell -> canvas is 480x480 (>= 400 CSS px)
  var TICK_MS = 120;

  var canvas = document.getElementById("snake");
  var ctx = canvas.getContext("2d");

  // ---- Game state ----------------------------------------------------------
  var snakeArr, curDir, nextDir, foodPos, scoreVal, alive_;

  var OPPOSITE = { up: "down", down: "up", left: "right", right: "left" };
  var DELTA = {
    up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0]
  };

  // ---- Core API ------------------------------------------------------------
  function reset() {
    var mid = Math.floor(H / 2);
    snakeArr = [[8, mid], [7, mid], [6, mid], [5, mid]]; // length 4, head first
    curDir = "right";
    nextDir = null;
    scoreVal = 0;
    alive_ = true;
    spawnFood();
    render();
  }

  function spawnFood() {
    var occupied = new Set(snakeArr.map(function (s) { return s[0] + "," + s[1]; }));
    var free = [];
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        if (!occupied.has(x + "," + y)) free.push([x, y]);
      }
    }
    if (free.length === 0) { foodPos = [0, 0]; return; }
    foodPos = free[Math.floor(Math.random() * free.length)];
  }

  function setFood(x, y) {
    // Used by grading to place food; also redraws.
    if (typeof x === "number" && typeof y === "number") {
      foodPos = [x, y];
      render();
    }
  }

  function setDir(d) {
    var dir = String(d).toLowerCase();
    if (!OPPOSITE[dir]) return;                 // ignore invalid input
    if (OPPOSITE[dir] === curDir) return;       // ignore 180° reversal
    nextDir = dir;                               // queue the turn
  }

  function tick() {
    if (!alive_) return;

    // Apply one queued turn, but never allow a reversal of current heading.
    if (nextDir && OPPOSITE[nextDir] !== curDir) curDir = nextDir;
    nextDir = null;

    var head = snakeArr[0];
    var d = DELTA[curDir];
    var nx = head[0] + d[0];
    var ny = head[1] + d[1];

    // Wall collision -> game over.
    if (nx < 0 || ny < 0 || nx >= W || ny >= H) { alive_ = false; return; }

    var willEat = (nx === foodPos[0] && ny === foodPos[1]);
    var newSnake = [[nx, ny]].concat(snakeArr);
    if (!willEat) newSnake.pop();               // tail steps away

    // Self collision -> game over.
    for (var i = 1; i < newSnake.length; i++) {
      if (newSnake[i][0] === nx && newSnake[i][1] === ny) { alive_ = false; return; }
    }

    snakeArr = newSnake;
    if (willEat) {
      scoreVal++;
      spawnFood();
    }
  }

  function getSnake() { return snakeArr.map(function (s) { return [s[0], s[1]]; }); }
  function getFood()  { return [foodPos[0], foodPos[1]]; }
  function isAlive()  { return alive_; }
  function getScore() { return scoreVal; }

  window.game = {
    reset: reset,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: getSnake,
    food: getFood,
    alive: isAlive,
    score: getScore
  };
  window.game.w = W;
  window.game.h = H;

  // ---- Rendering -----------------------------------------------------------
  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Background
    ctx.fillStyle = "#0d1117";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Subtle grid
    ctx.strokeStyle = "rgba(255,255,255,0.045)";
    ctx.lineWidth = 1;
    for (var i = 1; i < W; i++) {
      ctx.beginPath(); ctx.moveTo(i * CELL, 0); ctx.lineTo(i * CELL, canvas.height); ctx.stroke();
    }
    for (var j = 1; j < H; j++) {
      ctx.beginPath(); ctx.moveTo(0, j * CELL); ctx.lineTo(canvas.width, j * CELL); ctx.stroke();
    }

    // Food (glowing dot)
    var fx = foodPos[0] * CELL + CELL / 2;
    var fy = foodPos[1] * CELL + CELL / 2;
    ctx.save();
    ctx.strokeStyle = "rgba(255,77,109,0.35)";
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(fx, fy, CELL * 0.46, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = "#ff4d6d";
    ctx.beginPath(); ctx.arc(fx, fy, CELL * 0.34, 0, Math.PI * 2); ctx.fill();
    ctx.restore();

    // Snake (head first)
    for (var k = 0; k < snakeArr.length; k++) {
      var seg = snakeArr[k];
      var sx = seg[0] * CELL;
      var sy = seg[1] * CELL;
      if (k === 0) {
        ctx.fillStyle = "#9bffb4";
      } else {
        var t = snakeArr.length > 1 ? k / (snakeArr.length - 1) : 0;
        var light = 60 - t * 32;
        ctx.fillStyle = "hsl(140, 55%, " + light + "%)";
      }
      roundRect(sx + 1.5, sy + 1.5, CELL - 3, CELL - 3, 6);
      ctx.fill();
    }

    // Eyes on the head
    if (snakeArr.length) {
      var hx = snakeArr[0][0] * CELL + CELL / 2;
      var hy = snakeArr[0][1] * CELL + CELL / 2;
      var fwd = DELTA[curDir];
      var perp = [-fwd[1], fwd[0]];
      var off = CELL * 0.26;
      ctx.fillStyle = "#0d1117";
      for (var s = -1; s <= 1; s += 2) {
        var ex = hx + fwd[0] * off * 0.55 + perp[0] * off * s;
        var ey = hy + fwd[1] * off * 0.55 + perp[1] * off * s;
        ctx.beginPath(); ctx.arc(ex, ey, CELL * 0.085, 0, Math.PI * 2); ctx.fill();
      }
    }
  }

  // ---- UI loop wiring ------------------------------------------------------
  var timer = null;
  var running = false;

  function updateHUD() {
    var el = document.getElementById("score");
    if (!alive_) {
      el.textContent = "Game Over — Score: " + scoreVal;
    } else if (running) {
      el.textContent = "Score: " + scoreVal;
    } else {
      el.textContent = "Score: " + scoreVal + "   ·   Press Start or an arrow key";
    }
  }

  function startLoop() {
    if (running) return;
    running = true;
    updateHUD();
    timer = setInterval(function () {
      game.tick();
      updateHUD();
      if (!game.alive()) stopLoop();
    }, TICK_MS);
  }

  function stopLoop() {
    if (timer) { clearInterval(timer); timer = null; }
    running = false;
  }

  document.getElementById("start").addEventListener("click", startLoop);
  document.getElementById("pause").addEventListener("click", function () {
    if (running) stopLoop(); else startLoop();
    updateHUD();
  });
  document.getElementById("reset").addEventListener("click", function () {
    game.reset();
    updateHUD();
    if (!running) startLoop();
  });

  window.addEventListener("keydown", function (e) {
    var map = { ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right" };
    if (map[e.key]) {
      e.preventDefault();
      game.setDir(map[e.key]);
      if (!running) startLoop(); // let humans play immediately with the arrows
    } else if (e.code === "Space") {
      e.preventDefault();
      if (game.alive()) {
        if (running) stopLoop(); else startLoop();
        updateHUD();
      }
    }
  });

  // ---- Boot ----------------------------------------------------------------
  reset();
  updateHUD();
})();
</script>
</body>
</html>
